import url from 'url'
import { MockedRequest, RequestHandler } from './handlers/requestHandler'
import { MockedResponse } from './response'
import { getTimestamp } from './utils/getTimestamp'
import { styleStatusCode } from './utils/styleStatusCode'

export const log = (
  req: MockedRequest,
  res: MockedResponse,
  handler: RequestHandler<any>,
) => {
  const isLocal = req.url.startsWith(req.referrer)
  const parsedUrl = url.parse(req.url)
  const publicUrl = isLocal
    ? parsedUrl.pathname
    : url.format({
        protocol: parsedUrl.protocol,
        host: parsedUrl.host,
        pathname: parsedUrl.pathname,
      })

  setTimeout(() => {
    console.groupCollapsed(
      '[MSW] %s %s %s (%c%s%c)',
      getTimestamp(),
      req.method,
      publicUrl,
      styleStatusCode(res.status),
      res.status,
      'color:inherit',
    )
    console.log('Request', req)
    console.log('Handler:', {
      mask: handler.mask,
      resolver: handler.resolver,
    })
    console.log('Response', res)
    console.groupEnd()
  }, res.delay)
}

export const getTimestamp = () => {
  const now = new Date()
  return [now.getHours(), now.getMinutes(), now.getSeconds()]
    .map(String)
    .map((chunk) => chunk.slice(0, 2))
    .map((chunk) => chunk.padStart(2, '0'))
    .join(':')
}

export const styleStatusCode = (status: number) => {
  if (status < 300) {
    return 'color:#69AB32;'
  }

  if (status < 400) {
    return 'color:#F0BB4B;'
  }

  return 'color:#E95F5D;'
}

